use std::collections::HashMap;
use std::sync::Mutex;

struct Counter { counts: Mutex<HashMap<String, u64>> }

impl Counter {
    fn increment(&self, key: &str) {
        let mut counts = self.counts.lock().unwrap();  // acquire on entry
        *counts.entry(key.to_string()).or_insert(0) += 1;
    }                                                  // guard dropped here
}
